<?php
namespace Src\Inventario\Infrastructure\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class UsarRepuestoOrdenRequest extends FormRequest{public function authorize():bool{return$this->user()?->can('inventario.consumir')??false;}protected function prepareForValidation():void{$this->merge(['repuesto_id'=>$this->input('repuestoId'),'requerimiento_id'=>$this->input('requerimientoId')?:null]);}public function rules():array{return['repuesto_id'=>['required','uuid',Rule::exists('repuestos','id')->where('estado','activo')],'requerimiento_id'=>['nullable','uuid',Rule::exists('orden_repuestos_requeridos','id')->where('estado','<>','retirado')],'cantidad'=>['required','decimal:0,3','gt:0'],'observaciones'=>['nullable','string']];}}
